insert into public.split_templates (id, name, description, days_per_week, is_active) values
  ('ppl', 'Push / Pull / Legs', 'Classic 6-day structure: push, pull, legs — twice per week for high frequency.', 6, true),
  ('upper_lower', 'Upper / Lower', 'Four days alternating upper and lower. Strong balance of frequency and recovery.', 4, true),
  ('bro', 'Bro Split', 'Five body-part days: chest, back, shoulders, arms, legs. High volume per muscle.', 5, true),
  ('full_body', 'Full Body', 'Three full-body sessions. Ideal for HIT, foundations, or busy schedules.', 3, true),
  ('push_pull', 'Push / Pull', 'Four days alternating push (+ quads) and pull (+ hinges). Simple and effective.', 4, true)
insert into public.split_template_days (id, template_id, day_index, name, focus_muscles) values
  ('ppl-d0', 'ppl', 0, 'Push A', ARRAY['chest','shoulders','triceps']::text[]),
  ('ppl-d1', 'ppl', 1, 'Pull A', ARRAY['back','biceps','traps']::text[]),
  ('ppl-d2', 'ppl', 2, 'Legs A', ARRAY['quads','hamstrings','glutes','calves']::text[]),
  ('ppl-d3', 'ppl', 3, 'Push B', ARRAY['chest','shoulders','triceps']::text[]),
  ('ppl-d4', 'ppl', 4, 'Pull B', ARRAY['back','biceps','forearms']::text[]),
  ('ppl-d5', 'ppl', 5, 'Legs B', ARRAY['quads','hamstrings','glutes','calves']::text[]),
  ('ul-d0', 'upper_lower', 0, 'Upper A', ARRAY['chest','back','shoulders','biceps','triceps']::text[]),
  ('ul-d1', 'upper_lower', 1, 'Lower A', ARRAY['quads','hamstrings','glutes','calves','core']::text[]),
  ('ul-d2', 'upper_lower', 2, 'Upper B', ARRAY['chest','back','shoulders','biceps','triceps']::text[]),
  ('ul-d3', 'upper_lower', 3, 'Lower B', ARRAY['quads','hamstrings','glutes','calves','core']::text[]),
  ('bro-d0', 'bro', 0, 'Chest Day', ARRAY['chest','triceps']::text[]),
  ('bro-d1', 'bro', 1, 'Back Day', ARRAY['back','biceps','traps']::text[]),
  ('bro-d2', 'bro', 2, 'Shoulder Day', ARRAY['shoulders','traps','triceps']::text[]),
  ('bro-d3', 'bro', 3, 'Arm Day', ARRAY['biceps','triceps','forearms']::text[]),
  ('bro-d4', 'bro', 4, 'Leg Day', ARRAY['quads','hamstrings','glutes','calves']::text[]),
  ('fb-d0', 'full_body', 0, 'Full Body A', ARRAY['quads','chest','back','shoulders','core']::text[]),
  ('fb-d1', 'full_body', 1, 'Full Body B', ARRAY['hamstrings','glutes','chest','back','biceps']::text[]),
  ('fb-d2', 'full_body', 2, 'Full Body C', ARRAY['quads','shoulders','back','triceps','core']::text[]),
  ('pp-d0', 'push_pull', 0, 'Push A', ARRAY['chest','shoulders','triceps','quads']::text[]),
  ('pp-d1', 'push_pull', 1, 'Pull A', ARRAY['back','biceps','hamstrings','glutes']::text[]),
  ('pp-d2', 'push_pull', 2, 'Push B', ARRAY['chest','shoulders','triceps','quads']::text[]),
  ('pp-d3', 'push_pull', 3, 'Pull B', ARRAY['back','biceps','hamstrings','calves']::text[])
insert into public.exercises (id, name, primary_muscles, secondary_muscles, equipment, movement_pattern, default_sets, default_reps_min, default_reps_max, notes) values
  ('e349c696-171e-4719-a491-b588b2c8512f', 'Barbell Guillotine Bench Press', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position. As you breathe in, bring the bar down slowly until it is about 1 inch from your neck.'),
  ('ed47dee6-ad4a-42b9-a223-f0c0e466ac97', 'Bench Press - Powerlifting', ARRAY['triceps']::text[], ARRAY['chest','forearms','back','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.'),
  ('25fcf325-ff67-4c7a-a3c7-a857f9c6cd54', 'Dumbbell Squat To A Bench', ARRAY['quads']::text[], ARRAY['calves','glutes','hamstrings','back']::text[], ARRAY['dumbbell']::text[], 'squat', 4, 6, 10, 'Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs). Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.'),
  ('250dc7f0-29dc-4e89-abf4-0e386d96d0d7', 'Jerk Dip Squat', ARRAY['quads']::text[], ARRAY['core','calves']::text[], ARRAY['barbell']::text[], 'squat', 4, 6, 10, 'This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable. Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the weight to the starting position by driving forcefully though the feet.'),
  ('e094d92c-a0b9-4f41-a0ea-0df1d2226eef', 'Narrow Stance Squats', ARRAY['quads']::text[], ARRAY['calves','glutes','hamstrings','back']::text[], ARRAY['barbell']::text[], 'squat', 4, 6, 10, 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.'),
  ('42e38de4-b031-45bc-a502-d287f18a3d8b', 'Reverse Band Bench Press', ARRAY['triceps']::text[], ARRAY['chest','forearms','back','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell. Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.'),
  ('37b1e1a9-e2b4-44d5-a510-786a34fe7f08', 'Reverse Triceps Bench Press', ARRAY['triceps']::text[], ARRAY['chest','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.'),
  ('a46e9dc3-c47b-47b3-af18-adc989dfe61a', 'Wide-Grip Barbell Bench Press', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest.'),
  ('e5bf6afc-08a4-40f5-ab0f-c184da786eb9', 'Wide-Grip Decline Barbell Bench Press', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your lower chest.'),
  ('a282e62f-a73e-4cb6-a028-433bd8ad8d56', 'Arnold Dumbbell Press', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['dumbbell']::text[], 'vertical_push', 4, 6, 10, 'Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl. Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward.'),
  ('324b3b5e-1f4f-407d-a7a8-6a35b1c689b5', 'Barbell Bench Press - Medium Grip', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['barbell']::text[], 'horizontal_push', 3, 5, 8, 'Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.'),
  ('04388382-5ef8-46ff-a6a2-7aa669db1cce', 'Barbell Deadlift', ARRAY['back']::text[], ARRAY['calves','forearms','glutes','hamstrings','quads','traps']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'Stand in front of a loaded barbell. While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.'),
  ('36fdb1f8-7c2c-4262-a0be-932f8265cc94', 'Barbell Full Squat', ARRAY['quads']::text[], ARRAY['calves','glutes','hamstrings','back']::text[], ARRAY['barbell']::text[], 'squat', 4, 6, 10, 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.'),
  ('3aeb8def-5c4e-4c7a-acbc-0f91e8b6179d', 'Barbell Hack Squat', ARRAY['quads']::text[], ARRAY['calves','forearms','hamstrings']::text[], ARRAY['barbell']::text[], 'squat', 4, 6, 10, 'Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position. While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down.'),
  ('09ba7790-a21f-4c93-a6a9-ccedc19a07e4', 'Barbell Hip Thrust', ARRAY['glutes']::text[], ARRAY['calves','hamstrings']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.'),
  ('82bd87de-2c2e-488b-a86a-1321cccb99e2', 'Barbell Incline Bench Press - Medium Grip', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['barbell']::text[], 'horizontal_push', 3, 5, 8, 'Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on you upper chest.'),
  ('a9ed2ee6-4cf4-401f-a6f8-6960dc424a12', 'Barbell Lunge', ARRAY['quads']::text[], ARRAY['calves','glutes','hamstrings']::text[], ARRAY['barbell']::text[], 'lunge', 4, 6, 10, 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.'),
  ('84a5e4de-3ad2-41d6-a98a-6bd4e5eb3ea9', 'Barbell Rollout from Bench', ARRAY['core']::text[], ARRAY['glutes','hamstrings','back','shoulders']::text[], ARRAY['barbell']::text[], 'core', 3, 10, 15, 'Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position. To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement.'),
  ('14b0cf7f-1d31-469e-a8a8-ff5e21a663ea', 'Barbell Shoulder Press', ARRAY['shoulders']::text[], ARRAY['chest','triceps']::text[], ARRAY['barbell']::text[], 'vertical_push', 4, 6, 10, 'Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward). Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.'),
  ('19ac14ab-ea05-49bd-a9f4-720db7c28cbb', 'Barbell Squat To A Bench', ARRAY['quads']::text[], ARRAY['calves','glutes','hamstrings','back']::text[], ARRAY['barbell']::text[], 'squat', 3, 5, 8, 'This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth. '),
  ('5a1afca8-7c55-4106-a889-8b9fba625770', 'Bench Press with Chains', ARRAY['triceps']::text[], ARRAY['chest','back','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 3, 5, 8, 'Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar. Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar.'),
  ('e444cb63-a75b-4bd6-af83-302786b68dfc', 'Bent Over Two-Arm Long Bar Row', ARRAY['back']::text[], ARRAY['biceps']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 4, 6, 10, 'Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward. Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.'),
  ('7ef189b0-6979-437e-abbf-a1037a7ba136', 'Board Press', ARRAY['triceps']::text[], ARRAY['chest','forearms','back','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.'),
  ('dbfb1df0-e2c9-4656-a5d1-865527d96774', 'Box Squat', ARRAY['quads']::text[], ARRAY['glutes','calves','hamstrings','back']::text[], ARRAY['barbell']::text[], 'squat', 4, 6, 10, 'The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wider for more emphasis on the back, glutes, adductors, and hamstrings, or closer together for more quad development. Keep your head facing forward.'),
  ('fd2eeb78-e299-4659-a284-0358f2e0d351', 'Clean and Press', ARRAY['shoulders']::text[], ARRAY['core','calves','glutes','hamstrings','back','quads','traps','triceps']::text[], ARRAY['barbell']::text[], 'vertical_push', 4, 6, 10, 'Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position. Begin to pull the bar by extending the knees. Move your hips forward and raise the shoulders at the same rate while keeping the angle of the back constant; continue to lift the bar straight up while keeping it close to your body.'),
  ('d5c3cc78-4822-441f-a16b-d0ec5ce46866', 'Close-Grip Barbell Bench Press', ARRAY['triceps']::text[], ARRAY['chest','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 3, 5, 8, 'Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement.'),
  ('6ffa90f0-b3cc-4186-aa5f-959418009ae4', 'Cuban Press', ARRAY['shoulders']::text[], ARRAY['traps']::text[], ARRAY['dumbbell']::text[], 'vertical_push', 4, 6, 10, 'Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the "scarecrow" position. This will be your starting position. To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor.'),
  ('b9927f0e-f1ce-41d0-a33c-8892430d99c6', 'Decline Barbell Bench Press', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['barbell']::text[], 'horizontal_push', 3, 5, 8, 'Secure your legs at the end of the decline bench and slowly lay down on the bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.'),
  ('a418216e-1d42-4ce3-abfe-e4c36ef1d452', 'Decline Close-Grip Bench To Skull Crusher', ARRAY['triceps']::text[], ARRAY['chest','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Secure your legs at the end of the decline bench and slowly lay down on the bench. Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.'),
  ('4110ec24-b445-4280-a752-828254b1625b', 'Decline Dumbbell Bench Press', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 3, 5, 8, 'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width.'),
  ('feb15434-f513-4278-aaf7-557b12015884', 'Deficit Deadlift', ARRAY['back']::text[], ARRAY['forearms','glutes','hamstrings','quads','traps']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.'),
  ('d97a0312-626e-4b21-ab0a-3d9f02b60943', 'Drag Curl', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 4, 6, 10, 'Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position. As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders.'),
  ('24de271d-f021-4afe-af49-d03e36d8d850', 'Dumbbell Bench Press', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 3, 5, 8, 'Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other. Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.'),
  ('3710f136-36d9-4570-ac07-df17ab2f9b8b', 'Dumbbell Bench Press with Neutral Grip', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 3, 5, 8, 'Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted. Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.'),
  ('73f5364c-3dce-4034-adcf-7f27f45bf47a', 'Dumbbell Floor Press', ARRAY['triceps']::text[], ARRAY['chest','shoulders']::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 4, 6, 10, 'Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you. Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.'),
  ('9a462685-da45-468f-adf4-ccbcc4fda50b', 'Dumbbell One-Arm Shoulder Press', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['dumbbell']::text[], 'vertical_push', 4, 6, 10, 'Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight. Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface.'),
  ('0cda8550-1a84-4013-a867-ed95c2dc0b06', 'Dumbbell One-Arm Upright Row', ARRAY['shoulders']::text[], ARRAY['biceps','traps']::text[], ARRAY['dumbbell']::text[], 'horizontal_pull', 4, 6, 10, 'Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs. Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position.'),
  ('3f0687b0-c5d5-4cd9-aa9b-e11aaac6001e', 'Dumbbell Rear Lunge', ARRAY['quads']::text[], ARRAY['calves','glutes','hamstrings']::text[], ARRAY['dumbbell']::text[], 'lunge', 4, 6, 10, 'Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position. Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground. Keep the torso upright during the lunge; flexible hip flexors are important. A long lunge emphasizes the Gluteus Maximus; a short lunge emphasizes Quadriceps.'),
  ('46fcc8a9-2cf2-49bb-abfc-a7465b2de278', 'Dumbbell Shoulder Press', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['dumbbell']::text[], 'vertical_push', 4, 6, 10, 'While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs. Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position.'),
  ('14ce8304-c02e-4e34-aeeb-ec8d160ac08a', 'Elevated Back Lunge', ARRAY['quads']::text[], ARRAY['glutes','hamstrings']::text[], ARRAY['barbell']::text[], 'lunge', 4, 6, 10, 'Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you. Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position.'),
  ('a1e5438b-d8a2-4d71-a589-c22d50edb62c', 'Elevated Cable Rows', ARRAY['back']::text[], ARRAY['traps']::text[], ARRAY['cable']::text[], 'horizontal_pull', 4, 6, 10, 'Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height. Place it on the seat of the cable row machine.'),
  ('56792608-cbda-4cfc-a330-1aee389c56d1', 'Floor Press', ARRAY['triceps']::text[], ARRAY['chest','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks. Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or bouncing of the weight.'),
  ('2b46f61d-208a-45a3-a805-2b02ac311bca', 'Floor Press with Chains', ARRAY['triceps']::text[], ARRAY['chest','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks.'),
  ('5c3cb5b3-e74c-41b6-a6b8-a3cd39cd1aff', 'Frankenstein Squat', ARRAY['quads']::text[], ARRAY['core','calves','glutes','hamstrings']::text[], ARRAY['barbell']::text[], 'squat', 4, 6, 10, 'This drill teaches you the proper positioning of both the bar and your body during the clean and front squat. Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don''t round the thoracic spine.'),
  ('412d4451-b565-4c62-a9f1-25c05a1f3950', 'Front Barbell Squat To A Bench', ARRAY['quads']::text[], ARRAY['calves','glutes','hamstrings']::text[], ARRAY['barbell']::text[], 'squat', 3, 5, 8, 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat bench behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control. Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso.'),
  ('7833f229-c642-4e1e-adf9-e632648e716c', 'Front Squat (Clean Grip)', ARRAY['quads']::text[], ARRAY['core','glutes','hamstrings']::text[], ARRAY['barbell']::text[], 'squat', 4, 6, 10, 'To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position. Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head and elbows up at all times. This will be your starting position.'),
  ('c6a58872-9bf1-4ac3-a635-dff8fdd8d514', 'Full Range-Of-Motion Lat Pulldown', ARRAY['back']::text[], ARRAY['biceps','shoulders']::text[], ARRAY['cable']::text[], 'vertical_pull', 4, 6, 10, 'Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward. Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than forward. Return slowly to the starting position and repeat.'),
  ('cb1d1c52-5ae8-4bd7-a970-c74cb1da9959', 'Hammer Grip Incline DB Bench Press', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 3, 5, 8, 'Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.'),
  ('594a5d72-15a5-42a8-a070-423b97221465', 'High Cable Curls', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['cable']::text[], 'horizontal_pull', 4, 6, 10, 'Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position. Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps.'),
  ('d3865656-046c-4bc5-a491-e83de78d3420', 'Jefferson Squats', ARRAY['quads']::text[], ARRAY['calves','glutes','hamstrings','back','traps']::text[], ARRAY['barbell']::text[], 'squat', 4, 6, 10, 'Place a barbell on the floor. Stand in the middle of the bar length wise.'),
  ('19d5a3f8-d24a-4f91-a251-5af84af85566', 'Kneeling Squat', ARRAY['glutes']::text[], ARRAY['core','hamstrings','back']::text[], ARRAY['barbell']::text[], 'squat', 4, 6, 10, 'Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight. With your head looking forward, sit back with your butt until you touch your calves.'),
  ('89fcddb4-a605-4039-a453-5296e95d2acd', 'Narrow Stance Hack Squats', ARRAY['quads']::text[], ARRAY['calves','glutes','hamstrings']::text[], ARRAY['machine']::text[], 'squat', 4, 6, 10, 'Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided. Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times.'),
  ('cc2428dc-2e08-4bda-a737-4fc6dfba0748', 'Narrow Stance Leg Press', ARRAY['quads']::text[], ARRAY['calves','glutes','hamstrings']::text[], ARRAY['machine']::text[], 'squat', 4, 6, 10, 'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times. Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.'),
  ('2a8573e3-e117-4412-ad20-0ccac91ff3d9', 'Neck Press', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your neck.'),
  ('54d2523f-a60d-4ee8-af2f-be66fd4b36aa', 'One Arm Dumbbell Bench Press', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 3, 5, 8, 'Lie down on a flat bench with a dumbbell in one hand on top of your thigh. By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly.'),
  ('f7e26f60-f0a8-4dee-a538-9962cb8e4495', 'One Arm Floor Press', ARRAY['triceps']::text[], ARRAY['chest','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent. Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso).'),
  ('bb29d629-a43e-4a17-a716-2b449de06ffa', 'Pin Presses', ARRAY['triceps']::text[], ARRAY['chest','forearms','back','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion. The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting.'),
  ('f469b679-c9ba-4054-a1b3-73c91c6bc55c', 'Push Press - Behind the Neck', ARRAY['shoulders']::text[], ARRAY['calves','quads','triceps']::text[], ARRAY['barbell']::text[], 'vertical_push', 4, 6, 10, 'Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path. Using the momentum generated, finish pressing the weight overhead be extending through the arms.'),
  ('75c21a66-6082-43a7-a846-296b97eca94d', 'Reverse Grip Bent-Over Rows', ARRAY['back']::text[], ARRAY['biceps','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 4, 6, 10, 'Stand erect while holding a barbell with a supinated grip (palms facing up). Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.'),
  ('31a9ac9b-06c9-4247-a83f-ffed648a7aa0', 'Romanian Deadlift', ARRAY['hamstrings']::text[], ARRAY['calves','glutes','back']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion. Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.'),
  ('a36e1e06-cb18-4494-ace7-0fdd850e04f7', 'Romanian Deadlift from Deficit', ARRAY['hamstrings']::text[], ARRAY['forearms','glutes','back','traps']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion. Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings.'),
  ('f29a9830-36cd-4820-ad9b-a85d7189bed2', 'Seated Barbell Military Press', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['barbell']::text[], 'vertical_push', 4, 6, 10, 'Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.'),
  ('1f56fdab-1222-4ab8-af4a-7edc4fb3c934', 'Seated One-arm Cable Pulley Rows', ARRAY['back']::text[], ARRAY['biceps','traps']::text[], ARRAY['cable']::text[], 'horizontal_pull', 4, 6, 10, 'To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip.'),
  ('7cdb8b3c-9a01-48dd-aa83-051888ea3621', 'See-Saw Press (Alternating Side Press)', ARRAY['shoulders']::text[], ARRAY['core','triceps']::text[], ARRAY['dumbbell']::text[], 'vertical_push', 4, 6, 10, 'Grab a dumbbell with each hand and stand up erect. Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position.'),
  ('bc89e694-fb39-4c77-a1f3-aef25953d8bf', 'Snatch Deadlift', ARRAY['hamstrings']::text[], ARRAY['forearms','glutes','back','quads','traps']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward. Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees.'),
  ('40fcdbfb-6cca-45bb-aa2e-765e3f5b7bac', 'Snatch Shrug', ARRAY['traps']::text[], ARRAY['forearms','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 4, 6, 10, 'Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward. Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down.'),
  ('e95be3b8-75b8-469c-a684-6fb2a5df3f59', 'Standing Barbell Press Behind Neck', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['barbell']::text[], 'vertical_push', 4, 6, 10, 'This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.'),
  ('251e3155-7dd4-4d87-aaf7-9c914ca9ae06', 'Standing Palms-In Dumbbell Press', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['dumbbell']::text[], 'vertical_push', 4, 6, 10, 'Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position. Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbells up until your arms are fully extended.'),
  ('95f61b35-28d3-424f-a982-ae72d5d6541b', 'Stiff-Legged Barbell Deadlift', ARRAY['hamstrings']::text[], ARRAY['glutes','back']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.'),
  ('425f0ff9-3432-48af-a027-8795f87a533c', 'Straight Bar Bench Mid Rows', ARRAY['back']::text[], ARRAY['biceps']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 3, 5, 8, 'Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position. Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking.'),
  ('1420aefd-a65f-41a7-a32b-9a270e2dc13f', 'Sumo Deadlift', ARRAY['hamstrings']::text[], ARRAY['glutes','forearms','back','quads','traps']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms. Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.'),
  ('120cc9d3-e4c2-45c8-aa96-b8d131cd0713', 'Sumo Deadlift with Bands', ARRAY['hamstrings']::text[], ARRAY['glutes','forearms','back','quads','traps']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip.'),
  ('d17a2ffd-15e7-4181-a6f9-7d8bb2c67ddc', 'Sumo Deadlift with Chains', ARRAY['hamstrings']::text[], ARRAY['glutes','forearms','back','quads','traps']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the weight. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.'),
  ('29900d8f-8846-4dad-af9f-d0a7584a27ae', 'Upright Cable Row', ARRAY['traps']::text[], ARRAY['shoulders']::text[], ARRAY['cable']::text[], 'horizontal_pull', 4, 6, 10, 'Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the bar, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.'),
  ('a4e4faad-339c-4a1e-a728-0676dbd18015', 'V-Bar Pulldown', ARRAY['back']::text[], ARRAY['biceps','shoulders']::text[], ARRAY['cable']::text[], 'vertical_pull', 4, 6, 10, 'Sit down on a pull-down machine with a V-Bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.'),
  ('8309b5e8-5ea1-4343-a242-ab760e0e378a', 'Wide-Grip Pulldown Behind The Neck', ARRAY['back']::text[], ARRAY['biceps','shoulders']::text[], ARRAY['cable']::text[], 'vertical_pull', 4, 6, 10, 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.'),
  ('ac1e0323-09f2-4f7a-a6c9-b9fc726a2f12', 'Hyperextensions With No Hyperextension Bench', ARRAY['back']::text[], ARRAY['glutes','hamstrings']::text[], ARRAY['bodyweight']::text[], 'horizontal_push', 4, 6, 10, 'With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench. With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms.'),
  ('8932330d-0322-429e-a3ca-15bedc3c1751', 'Alternating Cable Shoulder Press', ARRAY['shoulders']::text[], ARRAY['triceps']::text[], ARRAY['cable']::text[], 'vertical_push', 3, 5, 8, 'Move the cables to the bottom of the tower and select an appropriate weight. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position.'),
  ('29e5ae3b-2831-4d46-a26d-0aa72940bc70', 'Anti-Gravity Press', ARRAY['shoulders']::text[], ARRAY['back','traps','triceps']::text[], ARRAY['barbell']::text[], 'vertical_push', 3, 5, 8, 'Place a bar on the ground behind the head of an incline bench. Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position.'),
  ('e2f91100-084e-4e30-a48d-4a1d05874013', 'Around The Worlds', ARRAY['chest']::text[], ARRAY['shoulders']::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 4, 6, 10, 'Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position. Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in as you perform this portion of the movement.'),
  ('61387c5b-9e8a-46fb-a909-05a59303f86f', 'Barbell Ab Rollout', ARRAY['core']::text[], ARRAY['back','shoulders']::text[], ARRAY['barbell']::text[], 'core', 3, 10, 15, 'For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position. While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.'),
  ('0262bf3d-89b5-4521-a130-a54b2ec5de0c', 'Barbell Glute Bridge', ARRAY['glutes']::text[], ARRAY['calves','hamstrings']::text[], ARRAY['barbell']::text[], 'horizontal_push', 4, 6, 10, 'Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor. Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet.'),
  ('f9917872-dba8-41ce-a510-d48aafea0082', 'Barbell Incline Shoulder Raise', ARRAY['shoulders']::text[], ARRAY['chest']::text[], ARRAY['barbell']::text[], 'vertical_push', 3, 5, 8, 'Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position. While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out.'),
  ('a9a06570-14f8-467b-af6e-5169eee44940', 'Barbell Rear Delt Row', ARRAY['shoulders']::text[], ARRAY['biceps','back']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 3, 5, 8, 'Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip. Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter "T". Now you are ready to begin the exercise.'),
  ('cdc9848b-fd42-4ec9-a53c-ad4258391c15', 'Bent-Arm Barbell Pullover', ARRAY['back']::text[], ARRAY['chest','shoulders','triceps']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 4, 6, 10, 'Lie on a flat bench with a barbell using a shoulder grip width. Hold the bar straight over your chest with a bend in your arms. This will be your starting position.'),
  ('8ed5c5fa-dccc-4c0f-a215-37c1855fe147', 'Bent-Arm Dumbbell Pullover', ARRAY['chest']::text[], ARRAY['back','shoulders','triceps']::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 4, 6, 10, 'Place a dumbbell standing up on a flat bench. Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well.'),
  ('868b49c3-fe0f-4bf5-a347-1e7163181b7e', 'Bent Over Barbell Row', ARRAY['back']::text[], ARRAY['biceps','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 3, 5, 8, 'Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position. Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.'),
  ('b67e579e-43ab-4773-ae9a-416d0b751c05', 'Bent Over One-Arm Long Bar Row', ARRAY['back']::text[], ARRAY['biceps','traps']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 3, 5, 8, 'Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward. Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.'),
  ('a93fd1c0-75d2-413d-a743-6f4a418eb683', 'Bent Over Two-Dumbbell Row', ARRAY['back']::text[], ARRAY['biceps','shoulders']::text[], ARRAY['dumbbell']::text[], 'horizontal_pull', 3, 5, 8, 'With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position. While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.'),
  ('14bd2018-e326-4cf5-a179-2705d9ef2ebe', 'Bent Over Two-Dumbbell Row With Palms In', ARRAY['back']::text[], ARRAY['biceps']::text[], ARRAY['dumbbell']::text[], 'horizontal_pull', 3, 5, 8, 'With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position. While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.'),
  ('871a1f9f-a078-493f-a6bc-d1e758bcfcfa', 'Cable Chest Press', ARRAY['chest']::text[], ARRAY['shoulders','triceps']::text[], ARRAY['cable']::text[], 'horizontal_push', 3, 5, 8, 'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement.'),
  ('97c615b0-76fb-43ee-a8cc-ae24f8c8f5e4', 'Clean', ARRAY['hamstrings']::text[], ARRAY['calves','forearms','glutes','back','quads','shoulders','traps']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 4, 6, 10, 'With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. '),
  ('acda82a5-1e80-484a-a3d6-a60835091b23', 'Clean Deadlift', ARRAY['hamstrings']::text[], ARRAY['forearms','glutes','back','quads','traps']::text[], ARRAY['barbell']::text[], 'hinge', 3, 5, 8, 'Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible. Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant back angle. Flare your knees out to the side to help keep them out of the bar''s path.'),
  ('66a2d467-bc0a-4e5a-a3ff-fed41a85f410', 'Clean Shrug', ARRAY['traps']::text[], ARRAY['forearms','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 3, 5, 8, 'Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward. Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.'),
  ('5115a2f8-7c39-4d00-a83b-d6384bca78a9', 'Close-Grip Dumbbell Press', ARRAY['triceps']::text[], ARRAY['chest','shoulders']::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 3, 5, 8, 'Place a dumbbell standing up on a flat bench. Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor.'),
  ('2989515b-160d-4cdf-a0dd-db51fe2cecbd', 'Decline Dumbbell Flyes', ARRAY['chest']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 3, 5, 8, 'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.'),
  ('f618724a-82cb-4fe5-a496-64297495592b', 'Dumbbell Clean', ARRAY['hamstrings']::text[], ARRAY['calves','forearms','glutes','back','quads','shoulders','traps']::text[], ARRAY['dumbbell']::text[], 'horizontal_pull', 4, 6, 10, 'Begin standing with a dumbbell in each hand with your feet shoulder width apart. Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position.'),
  ('49c5d394-4bdf-4709-ac41-3599a69d1f5b', 'Glute Ham Raise', ARRAY['hamstrings']::text[], ARRAY['calves','glutes']::text[], ARRAY['machine']::text[], 'horizontal_pull', 4, 6, 10, 'Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad. Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright.'),
  ('5ec8f13a-6b50-4e4b-a7fe-657ae7cb0080', 'Good Morning', ARRAY['hamstrings']::text[], ARRAY['core','glutes','back']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack. Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment.'),
  ('3da1f498-a0c1-431e-a912-286d02494b0a', 'Good Morning off Pins', ARRAY['hamstrings']::text[], ARRAY['core','glutes','back']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment. Begin the motion by extending through the hips with your glutes and hamstrings, and you are standing with the weight. Slowly lower the weight back to the pins returning to the starting position.'),
  ('9b25dff7-cbdd-4b35-a1a8-bcefd66d93ab', 'Hanging Bar Good Morning', ARRAY['hamstrings']::text[], ARRAY['core','glutes','back']::text[], ARRAY['barbell']::text[], 'hinge', 4, 6, 10, 'Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment.'),
  ('27479a5b-b05e-4658-a0cd-9099ba35b61c', 'JM Press', ARRAY['triceps']::text[], ARRAY['chest','shoulders']::text[], ARRAY['barbell']::text[], 'horizontal_push', 3, 5, 8, 'Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position. Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach the half way point, let the bar roll back about one inch by moving the upper arms towards your legs until they are perpendicular to the torso. Tip: Keep the bend at the elbows constant as you bring the upper arms forward.'),
  ('aa173a50-95ad-4263-a427-50a93af5b976', 'Kneeling Jump Squat', ARRAY['glutes']::text[], ARRAY['calves','hamstrings','quads']::text[], ARRAY['barbell']::text[], 'squat', 3, 5, 8, 'Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier. Sit back with your hips until your glutes touch your feet, keeping your head and chest up.'),
  ('1371939f-c8e0-4dd2-afcc-ee297f7e7744', 'Muscle Snatch', ARRAY['hamstrings']::text[], ARRAY['glutes','back','quads','shoulders','triceps']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 4, 6, 10, 'Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position. Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possible. The bar should be close to the body.'),
  ('474ebafc-40e9-46de-a5c2-f4fb730ec64c', 'Pallof Press With Rotation', ARRAY['core']::text[], ARRAY['chest','shoulders','triceps']::text[], ARRAY['cable']::text[], 'core', 3, 10, 15, 'Connect a standard handle to a tower, and position the cable to shoulder height. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable.'),
  ('933fd0d4-a585-42c7-aa5e-5a72eb15089a', 'Power Clean', ARRAY['hamstrings']::text[], ARRAY['calves','forearms','glutes','back','quads','shoulders','traps','triceps']::text[], ARRAY['barbell']::text[], 'horizontal_pull', 4, 6, 10, 'Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly. Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended.'),
  ('abf5232a-b8ad-4ccb-ae26-ed2812683167', 'Press Sit-Up', ARRAY['core']::text[], ARRAY['chest','shoulders','triceps']::text[], ARRAY['barbell']::text[], 'core', 3, 10, 15, 'To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position. While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles.'),
  ('52dd188a-97eb-4b9a-aca2-85aa873247e3', 'Smith Machine Close-Grip Bench Press', ARRAY['triceps']::text[], ARRAY['chest','shoulders']::text[], ARRAY['machine']::text[], 'vertical_pull', 3, 5, 8, 'Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.'),
  ('57c365a4-883e-4e3a-a285-3d45f49884d8', 'Standing Dumbbell Upright Row', ARRAY['traps']::text[], ARRAY['biceps','shoulders']::text[], ARRAY['dumbbell']::text[], 'horizontal_pull', 3, 5, 8, 'Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly touch your chin. Tip: Your elbows should drive the motion. As you lift the dumbbells, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.'),
  ('ec79350c-8b8d-47f6-a117-ab19ecbb652a', 'Bench Dips', ARRAY['triceps']::text[], ARRAY['chest','shoulders']::text[], ARRAY['bodyweight']::text[], 'horizontal_push', 3, 5, 8, 'For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position. Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.'),
  ('55b577d4-d794-4e87-a853-a1d482d7e233', 'Lying High Bench Barbell Curl', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['barbell']::text[], 'horizontal_push', 3, 8, 12, 'Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position. While keeping the elbows in and the upper arms stationary, curl the weight up in a semi-circular motion as you contract the biceps and exhale. Hold at the top of the movement for a second.'),
  ('3aafaa86-ccbe-4427-a806-dc87cd61facf', 'Barbell Ab Rollout - On Knees', ARRAY['core']::text[], ARRAY['back','shoulders']::text[], ARRAY['barbell']::text[], 'core', 3, 10, 15, 'Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor. Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.'),
  ('f873ff66-d583-41d5-abb8-27586056e2da', 'Cable Judo Flip', ARRAY['core']::text[], ARRAY[]::text[], ARRAY['cable']::text[], 'core', 3, 10, 15, 'Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands. Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip.'),
  ('3034b029-deb3-463f-ad2e-796e8abb9bc3', 'Cable Russian Twists', ARRAY['core']::text[], ARRAY[]::text[], ARRAY['cable']::text[], 'core', 3, 10, 15, 'Connect a standard handle attachment, and position the cable to a middle pulley position. Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.'),
  ('804d03a7-6882-431c-a246-527dc8e7f1b8', 'Landmine 180''s', ARRAY['core']::text[], ARRAY['glutes','back','shoulders']::text[], ARRAY['barbell']::text[], 'core', 3, 10, 15, 'Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight. Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position.'),
  ('1135fbc2-0114-4957-ae5e-84892f29685f', 'Pull Through', ARRAY['glutes']::text[], ARRAY['hamstrings','back']::text[], ARRAY['cable']::text[], 'horizontal_pull', 3, 5, 8, 'Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart. Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.'),
  ('bb3eadeb-33dd-4931-a8fb-40749b947c7c', 'Smith Machine Upright Row', ARRAY['traps']::text[], ARRAY['biceps','back','shoulders']::text[], ARRAY['machine']::text[], 'horizontal_pull', 3, 5, 8, 'To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight. Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position.'),
  ('c34e7708-3384-4713-acb1-79b9b9c02239', 'Spell Caster', ARRAY['core']::text[], ARRAY['glutes','shoulders']::text[], ARRAY['dumbbell']::text[], 'core', 3, 10, 15, 'Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position. Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso.'),
  ('a5a3b371-0a02-40e8-aa05-341d1cb50172', 'Standing Cable Lift', ARRAY['core']::text[], ARRAY['shoulders']::text[], ARRAY['cable']::text[], 'core', 3, 10, 15, 'Connect a standard handle on a tower, and move the cable to the lowest pulley position. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.'),
  ('6d179b4f-519b-429c-a7c6-b607967f8386', 'Standing Cable Wood Chop', ARRAY['core']::text[], ARRAY['shoulders']::text[], ARRAY['cable']::text[], 'core', 3, 10, 15, 'Connect a standard handle to a tower, and move the cable to the highest pulley position. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.'),
  ('54d7ee83-a8b5-4d1e-aff2-4c8ba9d8df65', 'Bent-Knee Hip Raise', ARRAY['core']::text[], ARRAY[]::text[], ARRAY['bodyweight']::text[], 'core', 3, 10, 15, 'Lay flat on the floor with your arms next to your sides. Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.'),
  ('0fd8a738-69a6-4c81-a3f0-a3a2a9bff7d0', 'Bent Press', ARRAY['core']::text[], ARRAY['glutes','hamstrings','back','quads','shoulders','triceps']::text[], ARRAY['kettlebell']::text[], 'core', 3, 10, 15, 'Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position. Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpendicular to the ground.'),
  ('73a4ee37-ea7a-4624-a63a-9452c80743f1', 'Bottoms-Up Clean From The Hang Position', ARRAY['forearms']::text[], ARRAY['biceps','shoulders']::text[], ARRAY['kettlebell']::text[], 'horizontal_pull', 4, 6, 10, 'Initiate the exercise by standing upright with a kettlebell in one hand. Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.'),
  ('aaf500da-0b06-493b-a615-f8f106c706db', 'Calf Raise On A Dumbbell', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise. Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position.'),
  ('87fd555f-a4be-43a2-a373-c3d24831342c', 'Double Kettlebell Windmill', ARRAY['core']::text[], ARRAY['glutes','hamstrings','shoulders','triceps']::text[], ARRAY['kettlebell']::text[], 'core', 3, 10, 15, 'Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out kettlebell.'),
  ('8ffb03e6-3dbd-4211-a961-b6aab3e5aa31', 'Dumbbell Prone Incline Curl', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way). Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor.'),
  ('905a50ba-117c-4900-aeea-e4f03f5cd0cf', 'Flat Bench Leg Pull-In', ARRAY['core']::text[], ARRAY[]::text[], ARRAY['bodyweight']::text[], 'core', 3, 10, 15, 'Lie on an exercise mat or a flat bench with your legs off the end. Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position.'),
  ('c2007dde-e860-4d98-a647-b29c049ed1f8', 'Gorilla Chin/Crunch', ARRAY['core']::text[], ARRAY['biceps','back']::text[], ARRAY['bodyweight']::text[], 'core', 3, 10, 15, 'Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width. Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position.'),
  ('76d65dcb-4aa6-40b9-a1ed-313822c4a09a', 'Hip Extension with Bands', ARRAY['glutes']::text[], ARRAY['hamstrings']::text[], ARRAY['band']::text[], 'horizontal_push', 3, 5, 8, 'Secure one end of the band to the lower portion of a post and attach the other to one ankle. Facing the attachment point of the band, hold on to the column to stabilize yourself.'),
  ('b94a7170-5675-4198-abfb-4fdc6d1a2813', 'Kettlebell Sumo High Pull', ARRAY['traps']::text[], ARRAY['glutes','hamstrings','quads','shoulders']::text[], ARRAY['kettlebell']::text[], 'horizontal_pull', 4, 6, 10, 'Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position. Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position.'),
  ('d5a9ab89-527d-4116-adfe-b251cf8c9068', 'Lying Cable Curl', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['cable']::text[], 'isolation', 3, 8, 12, 'Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip. Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight.'),
  ('4b8d0e62-06ff-436a-a32e-4a17cf91a13f', 'Overhead Cable Curl', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['cable']::text[], 'vertical_push', 3, 8, 12, 'To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side. Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders.'),
  ('dd9bbab8-b680-434e-acc7-21d850f3dc6f', 'Palms-Down Dumbbell Wrist Curl Over A Bench', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 3, 8, 12, 'Start out by placing two dumbbells on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench.'),
  ('f0e82230-a584-4a96-ac4b-5ef8a5b9a2ed', 'Palms-Down Wrist Curl Over A Bench', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['barbell']::text[], 'horizontal_push', 3, 8, 12, 'Start out by placing a barbell on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench.'),
  ('f70f22ee-bbd6-4265-a71d-00ec0ac484f8', 'Palms-Up Barbell Wrist Curl Over A Bench', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['barbell']::text[], 'horizontal_push', 3, 8, 12, 'Start out by placing a barbell on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench.'),
  ('936269fb-2a06-45aa-a805-428841f7da6f', 'Palms-Up Dumbbell Wrist Curl Over A Bench', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 3, 8, 12, 'Start out by placing two dumbbells on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench.'),
  ('37f68d40-f637-46c7-a0af-2782f80621c2', 'Seated Close-Grip Concentration Barbell Curl', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['barbell']::text[], 'isolation', 3, 8, 12, 'Sit down on a flat bench with a barbell or E-Z Bar in front of you in between your legs. Your legs should be spread with the knees bent and the feet on the floor. Use your arms to pick the barbell up and place the back of your upper arms on top of your inner thighs (around three and a half inches away from the front of the knee). A supinated grip closer than shoulder width is needed to perform this exercise. Tip: Your arm should be extended at arms length and the barbell should be above the floor. This will be your starting position.'),
  ('eab02967-03b4-474c-a8e0-ddcc93375e48', 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Sit on a flat bench with a dumbbell in your right hand. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.'),
  ('1eb6783a-78d9-47c3-aa1b-5283698594fa', 'Standing Dumbbell Calf Raise', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position. With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top contraction for a second.'),
  ('9a0b7a89-a9ad-4c6d-a8a9-26e4eea0ad6d', 'Standing Dumbbell Reverse Curl', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position. While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the muscle.'),
  ('c54bf9ce-4063-40e4-a597-40ed35e5f806', 'Standing Inner-Biceps Curl', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Stand up with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Your legs should be at about shoulder''s width apart from each other. Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position.'),
  ('62a87aac-d169-461a-ad38-c6056a201d68', 'Standing One-Arm Cable Curl', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['cable']::text[], 'isolation', 3, 8, 12, 'Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight. Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance.'),
  ('288ac5b8-854b-489d-a305-2cd5623462b6', 'Standing One-Arm Dumbbell Curl Over Incline Bench', ARRAY['biceps']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'horizontal_push', 3, 8, 12, 'Stand on the back side of an incline bench as if you were going to be a spotter for someone. Have a dumbbell in one hand and rest it across the incline bench with a supinated (palms up) grip. Position your non lifting hand at the corner or side of the incline bench. The chest should be pressed against the top part of the incline and your feet should be pressed against the floor at a wide stance. This is the starting position.'),
  ('f8128d21-0134-42c1-a87d-44b9be0f5196', 'Step-up with Knee Raise', ARRAY['glutes']::text[], ARRAY['hamstrings','quads']::text[], ARRAY['bodyweight']::text[], 'horizontal_push', 3, 5, 8, 'Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position. Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.'),
  ('f70d78e5-6623-47ff-a72d-d963488150bb', 'Upright Row - With Bands', ARRAY['traps']::text[], ARRAY['shoulders']::text[], ARRAY['band']::text[], 'horizontal_pull', 3, 5, 8, 'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continue to lift the handles until they nearly touches your chin. Tip: Your elbows should drive the motion. As you lift the handles, your elbows should always be higher than your forearms. Also, keep your torso stationary and pause for a second at the top of the movement.'),
  ('3889b768-88fc-4244-a2a4-e3f29a896630', 'Zottman Curl', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Make sure the palms of the hands are facing each other. This will be your starting position.'),
  ('526c16e0-a31e-4c0c-a691-055b0c23f8a0', 'Zottman Preacher Curl', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position. As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched.'),
  ('ea57e75d-417e-47f6-ab61-e4b9ef3f81bf', 'Alternate Hammer Curl', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso. The palms of the hands should be facing your torso. This will be your starting position.'),
  ('875dc8dd-a683-4e6e-af86-d8b880235364', 'Alternate Incline Dumbbell Curl', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position. While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.'),
  ('a6972ca7-1926-4ef1-a463-51e898ebc759', 'Barbell Curl', ARRAY['biceps']::text[], ARRAY['forearms']::text[], ARRAY['barbell']::text[], 'isolation', 3, 8, 12, 'Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.'),
  ('a51e4651-7e9d-4825-a6d3-6d699cd76d41', 'Barbell Seated Calf Raise', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['barbell']::text[], 'isolation', 3, 8, 12, 'Place a block about 12 inches in front of a flat bench. Sit on the bench and place the ball of your feet on the block.'),
  ('1235e70c-6db2-4c69-ac18-72d9d6063e3d', 'Barbell Shrug', ARRAY['traps']::text[], ARRAY[]::text[], ARRAY['barbell']::text[], 'isolation', 3, 8, 12, 'Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position. Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.'),
  ('4dcad7ae-9175-4625-af45-a86287f2c0d5', 'Barbell Shrug Behind The Back', ARRAY['traps']::text[], ARRAY['forearms','back']::text[], ARRAY['barbell']::text[], 'isolation', 3, 8, 12, 'Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position. Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should remain stretched out at all times.'),
  ('c9b7f2c8-4fa5-4f68-aecc-97e9646e6b1c', 'Cable Shrugs', ARRAY['traps']::text[], ARRAY[]::text[], ARRAY['cable']::text[], 'isolation', 3, 8, 12, 'Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip. Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position.'),
  ('beb064eb-c3a3-417a-a014-e7c25c28580c', 'Cable Wrist Curl', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['cable']::text[], 'isolation', 3, 8, 12, 'Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment. Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees.'),
  ('8725f028-441e-4ada-a3f4-c6adcd1d8bec', 'Dumbbell Lying Pronation', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it. Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.'),
  ('844be332-58c4-4094-a955-20e82c8d2b91', 'Dumbbell Lying Supination', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it. Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm.'),
  ('3423c221-778b-4d65-a64c-209400cc8a5d', 'Dumbbell Seated One-Leg Calf Raise', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Place a block on the floor about 12 inches from a flat bench. Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.'),
  ('b91d6aea-840f-45e3-a140-dbba5048d20f', 'Dumbbell Shrug', ARRAY['traps']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides. Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.'),
  ('867bb1a0-615d-4ff1-aca6-a9a4d3616d49', 'Finger Curls', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['barbell']::text[], 'isolation', 3, 8, 12, 'Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position.'),
  ('7960c6eb-290e-4f96-a662-6e460b8a9f76', 'Flutter Kicks', ARRAY['glutes']::text[], ARRAY['hamstrings']::text[], ARRAY['bodyweight']::text[], 'horizontal_pull', 3, 5, 8, 'On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge. Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.'),
  ('ffbbe46b-f6df-4715-a2b0-1b8e48e30527', 'Glute Kickback', ARRAY['glutes']::text[], ARRAY['hamstrings']::text[], ARRAY['bodyweight']::text[], 'horizontal_push', 3, 5, 8, 'Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position. As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.'),
  ('ae320836-afa8-4a9c-a16c-2ea9f8ac209a', 'Hip Lift with Band', ARRAY['glutes']::text[], ARRAY['calves','hamstrings']::text[], ARRAY['band']::text[], 'horizontal_push', 3, 5, 8, 'After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move. Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position.'),
  ('4fbbe7b4-47d8-4563-a938-702b12e53c2e', 'Monster Walk', ARRAY['glutes']::text[], ARRAY[]::text[], ARRAY['band']::text[], 'horizontal_pull', 3, 5, 8, 'Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart. To begin, take short steps forward alternating your left and right foot.'),
  ('e3f62c2f-9c0e-492e-a1e3-bde3d7c78b0b', 'One-Legged Cable Kickback', ARRAY['glutes']::text[], ARRAY['hamstrings']::text[], ARRAY['cable']::text[], 'isolation', 3, 8, 12, 'Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle. Face the weight stack from a distance of about two feet, grasping the steel frame for support.'),
  ('5b75b148-a57d-4009-aaf0-5834e977ea98', 'Rocking Standing Calf Raise', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['barbell']::text[], 'isolation', 3, 8, 12, 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck). Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.'),
  ('fd0324d3-d35b-4d58-ab29-1c70b7d8eaff', 'Seated Dumbbell Palms-Down Wrist Curl', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Start out by placing two dumbbells on the floor in front of a flat bench. Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.'),
  ('cb358008-1149-496a-a0c1-c6d4220f98ae', 'Seated Dumbbell Palms-Up Wrist Curl', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Start out by placing two dumbbells on the floor in front of a flat bench. Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor.'),
  ('714e2d97-5bfd-426d-accf-030f259e5820', 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['dumbbell']::text[], 'isolation', 3, 8, 12, 'Sit on a flat bench with a dumbbell in your right hand. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.'),
  ('5b5fa9b0-e9fe-4378-ac64-3ade3a6d65ac', 'Seated Palm-Up Barbell Wrist Curl', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['barbell']::text[], 'isolation', 3, 8, 12, 'Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.'),
  ('ffda6d52-30e9-470a-ae54-aa8bbcc7200f', 'Seated Palms-Down Barbell Wrist Curl', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['barbell']::text[], 'isolation', 3, 8, 12, 'Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart.'),
  ('69975b22-0bf5-43fd-a14f-72b4ebe77f55', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', ARRAY['forearms']::text[], ARRAY[]::text[], ARRAY['cable']::text[], 'isolation', 3, 8, 12, 'Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it. Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up.'),
  ('6f128ad3-ddf1-4581-a984-12538a7f9a9f', 'Standing Barbell Calf Raise', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['barbell']::text[], 'isolation', 3, 8, 12, 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck). Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.'),
  ('9a4e7f16-965e-4d12-a4c5-0a7a71b8b2a6', 'Calf-Machine Shoulder Shrug', ARRAY['traps']::text[], ARRAY[]::text[], ARRAY['machine']::text[], 'vertical_pull', 3, 8, 12, 'Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position. Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second.'),
  ('dec39ee2-47bc-4dc8-a324-70f072e8cf7d', 'Calf Press', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['machine']::text[], 'isolation', 3, 8, 12, 'Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform. Select an appropriate weight, and grasp the handles. This will be your starting position.'),
  ('6e4678e7-dd68-4e11-a52e-0e811069ad4f', 'Calf Press On The Leg Press Machine', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['machine']::text[], 'squat', 3, 8, 12, 'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of performing the exercise.) Your torso and the legs should make perfect 90-degree angle. Now carefully place your toes and balls of your feet on the lower portion of the platform with the heels extending off. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.'),
  ('a45f73dd-863b-4a6e-a9f8-b996565f84df', 'Leverage Shrug', ARRAY['traps']::text[], ARRAY['forearms']::text[], ARRAY['machine']::text[], 'isolation', 3, 8, 12, 'Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up.'),
  ('49bc882b-6dec-46b9-a309-58c420a31ade', 'Seated Calf Raise', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['machine']::text[], 'isolation', 3, 8, 12, 'Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter. Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.'),
  ('9b2dd84e-4506-4068-ad14-52b6060bf5e4', 'Smith Machine Behind the Back Shrug', ARRAY['traps']::text[], ARRAY['shoulders']::text[], ARRAY['machine']::text[], 'vertical_pull', 3, 8, 12, 'With the bar at thigh level, load an appropriate weight. Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position.'),
  ('3c753489-ebc7-40f1-a871-bc1fe13faf5d', 'Smith Machine Calf Raise', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['machine']::text[], 'vertical_pull', 3, 8, 12, 'Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders. Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position.'),
  ('20a42423-1107-4090-adcf-6f0105719ea5', 'Smith Machine Reverse Calf Raises', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['machine']::text[], 'vertical_pull', 3, 8, 12, 'Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar. Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance.'),
  ('4ee41542-b125-46d9-ae88-121a572403c0', 'Standing Calf Raises', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['machine']::text[], 'isolation', 3, 8, 12, 'Adjust the padded lever of the calf raise machine to fit your height. Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.'),
  ('445f1adc-85c8-4d3e-ad4f-8146e16d4848', 'Calf Raises - With Bands', ARRAY['calves']::text[], ARRAY[]::text[], ARRAY['band']::text[], 'isolation', 3, 8, 12, 'Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides. While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.'),
  ('d2634733-f34d-4c70-a18b-241fb7ad748c', 'Thigh Abductor', ARRAY['glutes']::text[], ARRAY[]::text[], ARRAY['machine']::text[], 'isolation', 3, 8, 12, 'To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position. Slowly press against the machine with your legs to move them away from each other while exhaling.'),
  ('ce798832-b97e-49d3-a1f1-5420d13c19b0', 'Thigh Adductor', ARRAY['glutes']::text[], ARRAY['hamstrings']::text[], ARRAY['machine']::text[], 'isolation', 3, 8, 12, 'To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position. Slowly press against the machine with your legs to move them towards each other while exhaling.'),
  ('8ab19fb6-51af-44e4-a06d-2bdd9af2f948', 'Band Hip Adductions', ARRAY['glutes']::text[], ARRAY[]::text[], ARRAY['band']::text[], 'isolation', 3, 8, 12, 'Anchor a band around a solid post or other object. Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.'),
  ('09ec620e-f068-4fc6-a0d7-8e88b2be4285', 'Butt Lift (Bridge)', ARRAY['glutes']::text[], ARRAY['hamstrings']::text[], ARRAY['bodyweight']::text[], 'isolation', 3, 8, 12, 'Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position. Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.'),
  ('c377cb1f-aabe-4b51-a701-1fdc37bedb2f', 'Isometric Neck Exercise - Front And Back', ARRAY['traps']::text[], ARRAY[]::text[], ARRAY['bodyweight']::text[], 'isolation', 3, 8, 12, 'With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head. Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.'),
  ('da001ac9-d08c-4bb0-a539-b8bc76896b0e', 'Isometric Neck Exercise - Sides', ARRAY['traps']::text[], ARRAY[]::text[], ARRAY['bodyweight']::text[], 'isolation', 3, 8, 12, 'With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head. Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.')
